BeatSurge.customGLSL:
// @node beatSurge
// @title Beat Surge
// @category custom
// @description Eased push for a phase 0..1 (Beat.phase or Beat.bar): easeOutCubic(phase) - phase, times amount. It rushes ahead right after the beat and glides back to 0 by the next one, so adding it to an angle or a scroll makes motion step on the beat without drifting (net zero per beat, 0 when amount is 0).
float beatSurge(float phase, float amount) {
    float p = clamp(phase, 0.0, 1.0);
    float q = 1.0 - p;
    return amount * (1.0 - q * q * q - p);
}

SynthEnv.customGLSL:
// @node synthEnv
// @title Synth Env
// @category custom
// @description Synthwave environment seen along a ray: dusk sky, stars, a striped HDR sun and a scrolling neon grid floor. Feed it camera rays for the background and reflected / refracted rays for materials. music (0 = silent): a pulse of light rolls down the grid and lands on the camera on every beat, and the sun stripes open up on every bar.
float synthHash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float synthNoise1(float x) {
    float i = floor(x);
    float f = fract(x);
    float a = synthHash(vec2(i, 17.0));
    float b = synthHash(vec2(i + 1.0, 17.0));
    return mix(a, b, f * f * (3.0 - 2.0 * f));
}

float synthRidge(float x) {
    float v = 0.0;
    float amp = 0.55;
    for (int i = 0; i < 4; i++) {
        v += amp * (1.0 - abs(synthNoise1(x) * 2.0 - 1.0));
        x *= 2.13;
        amp *= 0.5;
    }
    return v;
}

// One mountain layer seen along rd: returns (coverage, color) packed as vec4
vec4 synthMountains(vec3 rd, float az, float scale, float height, float seed, vec3 body, vec3 rim, float time) {
    float valley = smoothstep(0.1, 0.4, abs(az));
    float m = (0.012 + height * synthRidge(az * scale + seed)) * (0.35 + 0.65 * valley);
    float e = asin(clamp(rd.y, -1.0, 1.0));
    float inside = 1.0 - smoothstep(-0.0015, 0.0015, e - m);
    float depth = clamp((m - e) / max(m, 1e-3), 0.0, 1.0);
    // Wireframe: contour lines that follow the ridge, plus vertical lines in azimuth
    float contour = abs(fract(depth * 9.0 - time * 0.15) - 0.5);
    float vert = abs(fract(az * 38.0) - 0.5);
    float wire = max(1.0 - smoothstep(0.0, fwidth(depth * 9.0) * 1.5, contour),
                     1.0 - smoothstep(0.0, fwidth(az * 38.0) * 1.5, vert));
    vec3 col = body * (0.35 + 0.65 * depth);
    col += rim * wire * (1.0 - depth) * 0.55;
    col += rim * exp(-abs(m - e) * 160.0) * 1.6;      // hot ridge line (abs: never overflows)
    return vec4(col, inside * step(0.0, e + 0.002));
}

vec3 synthEnv(vec3 ro, vec3 rd, float time, float music) {
    rd = dot(rd, rd) > 1e-10 ? normalize(rd) : vec3(0.0, 1.0, 0.0);
    vec3 sunDir = normalize(vec3(0.0, 0.11, -1.0));

    // Sky: hot horizon -> violet dusk -> night
    float h = clamp(rd.y * 2.2, 0.0, 1.0);
    vec3 sky = mix(vec3(1.0, 0.28, 0.42), vec3(0.32, 0.04, 0.45), smoothstep(0.0, 0.3, h));
    sky = mix(sky, vec3(0.012, 0.008, 0.04), smoothstep(0.22, 1.0, h));

    // Stars
    vec2 st = vec2(atan(rd.x, -rd.z), asin(clamp(rd.y, -1.0, 1.0))) * 90.0;
    vec2 cell = floor(st);
    float rnd = synthHash(cell);
    float star = step(0.975, rnd) * (1.0 - smoothstep(0.0, 0.12, length(fract(st) - 0.5)));
    star *= 0.6 + 0.4 * sin(time * 3.0 + rnd * 40.0);
    sky += vec3(0.9, 0.85, 1.0) * star * smoothstep(0.08, 0.45, rd.y) * 1.5;

    // Sun: disc in the sun's tangent plane, scrolling stripes on the lower half
    vec3 right = normalize(cross(sunDir, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, sunDir);
    float facing = dot(rd, sunDir);
    vec2 q = vec2(dot(rd, right), dot(rd, up)) / max(facing, 1e-3);
    float r = length(q);
    float sunR = 0.18;
    float disc = (1.0 - smoothstep(sunR - 0.008, sunR, r)) * step(0.0, facing);
    float band = fract(q.y * 34.0 + time * 0.5);
    float gap = clamp((0.08 - q.y) / sunR, 0.0, 1.0) * 0.8;
    // Music: on each bar the stripes thin out (the sun opens up), then ease back over the bar
    float barEnv = music * u_beatConfidence * smoothstep(0.25, 0.75, u_beatTrust) * exp(-u_barPhase * 5.0) * smoothstep(0.0, 0.02, u_barPhase);
    gap *= 1.0 - 0.6 * barEnv;
    disc *= gap > 0.07 ? smoothstep(gap - 0.04, gap + 0.04, band) : 1.0;
    vec3 sunCol = mix(vec3(1.0, 0.1, 0.55), vec3(1.0, 0.82, 0.22), smoothstep(-sunR, sunR * 0.8, q.y));
    sky = mix(sky, sunCol * (1.35 + 0.5 * barEnv), disc);
    sky += vec3(1.0, 0.25, 0.5) * exp(-r * 4.0) * 0.4 * step(0.0, facing);

    // Horizon haze, then two mountain ranges in front of the sun
    float az = atan(rd.x, -rd.z);
    sky += vec3(1.0, 0.32, 0.62) * exp(-max(rd.y, 0.0) * 22.0) * 0.35;
    vec4 far = synthMountains(rd, az, 2.2, 0.1, 5.9, vec3(0.20, 0.08, 0.38), vec3(0.35, 0.75, 1.0), time);
    sky = mix(sky, far.rgb + vec3(0.30, 0.10, 0.35) * 0.25, far.a);
    vec4 near = synthMountains(rd, az, 4.1, 0.05, 11.3, vec3(0.06, 0.012, 0.11), vec3(1.0, 0.2, 0.72), time);
    sky = mix(sky, near.rgb, near.a);

    // Floor: ray / plane hit, anti-aliased glowing grid scrolling toward the camera
    float floorY = -1.9;
    float down = step(rd.y, -0.0005) * step(floorY, ro.y);
    float t = (floorY - ro.y) / min(rd.y, -0.0005);
    vec3 P = ro + rd * t;
    vec2 g = P.xz + vec2(0.0, time * 1.6);
    vec2 dist = 0.5 - abs(fract(g) - 0.5);
    vec2 w = fwidth(g) + 0.001;
    vec2 core = 1.0 - smoothstep(vec2(0.0), w * 1.5, dist);
    vec2 halo = exp(-dist * 9.0);
    float lineCore = max(core.x, core.y);
    float lineHalo = max(halo.x, halo.y);
    float fog = exp(-t * 0.028);
    vec3 lineCol = mix(vec3(1.0, 0.16, 0.72), vec3(0.25, 0.75, 1.0), smoothstep(6.0, 34.0, t));
    // Music: a beat pulse rolls toward the camera along the grid (far lines lead, near lines land on the beat)
    float gph = fract(u_beatPhase + max(t - 2.0, 0.0) * 0.012);
    float gridFlash = music * u_beatConfidence * smoothstep(0.25, 0.75, u_beatTrust) * smoothstep(0.0, 0.03, gph) * exp(-gph * 5.0);
    vec3 fl = vec3(0.025, 0.008, 0.06) + lineCol * (lineCore * 2.4 * (1.0 + 0.5 * gridFlash) + lineHalo * 0.25 * (1.0 + 1.4 * gridFlash));
    vec3 refl = reflect(rd, vec3(0.0, 1.0, 0.0));
    float sunAz = atan(rd.x, -rd.z);
    float shimmer = 0.55 + 0.45 * sin(t * 2.5 - time * 3.0);
    float streakMask = exp(-abs(sunAz) * 14.0) * smoothstep(2.0, 18.0, t) * shimmer;
    vec3 streakCol = mix(vec3(1.0, 0.15, 0.55), vec3(1.0, 0.75, 0.3), smoothstep(8.0, 40.0, t)) * streakMask * 0.9;
    vec3 haze = mix(vec3(0.32, 0.07, 0.36), vec3(0.95, 0.32, 0.42), exp(-abs(sunAz) * 2.5));
    fl = mix(haze, fl, fog) + streakCol;

    vec3 col = mix(sky, fl, down);
    // Thin hot line on the horizon
    col += vec3(1.0, 0.45, 0.7) * exp(-abs(rd.y) * 140.0) * 0.9;
    col += vec3(0.55, 0.25, 1.0) * exp(-abs(rd.y) * 30.0) * 0.18;
    return col;
}

HyperbolicHoneycomb.customGLSL:
// @node hyperbolicHoneycomb
// @title Hyperbolic Honeycomb
// @category custom
// @description Ray traces the order-5 cubic honeycomb {4,3,5}: echo delays every cube by its distance (seconds per unit), so farther cubes show the past. hyperbolic space tiled by cubes, five around every edge. Every cell holds a spinning cube that casts two volumetric light cones. Rays hop between cells by Lorentz reflections in the hyperboloid model, so every cube is a true copy. music (0 = silent) makes every beat ripple outward: lamps and light cones flare and cubes surge forward as the beat wavefront (ripple = beats of delay per unit of distance) reaches them. Returns HDR color.

// Minkowski inner product (+,+,+,-)
float hbDot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

vec4 hbReflect(vec4 x, vec4 n) {
    return x - 2.0 * hbDot(x, n) * n;
}

// Outward unit normal of cell face i: Klein plane x_j = +-a
vec4 hbFace(int i, float a) {
    int j = i / 2;
    float s = (i - j * 2 == 0) ? 1.0 : -1.0;
    vec3 e = j == 0 ? vec3(1.0, 0.0, 0.0) : (j == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0));
    return vec4(e * s, a) / sqrt(1.0 - a * a);
}

float hbAtanh(float x) {
    x = clamp(x, 0.0, 0.99999);
    return 0.5 * log((1.0 + x) / (1.0 - x));
}

vec4 hbPoint(vec4 p) {
    return p / sqrt(max(-hbDot(p, p), 1e-9));
}

// Project onto the tangent space at p and normalize
vec4 hbTangent(vec4 v, vec4 p) {
    v += hbDot(v, p) * p;
    return v / sqrt(max(hbDot(v, v), 1e-9));
}

// M * sigma_n, where sigma_n is the Lorentz reflection in the plane with normal n
mat4 hbReflectMat(mat4 M, vec4 n) {
    return M - 2.0 * outerProduct(M * n, vec4(n.xyz, -n.w));
}

// M^-1 x for a Lorentz matrix M (M^-1 = eta M^T eta)
vec4 hbInvApply(mat4 M, vec4 x) {
    vec4 y = transpose(M) * vec4(x.xyz, -x.w);
    return vec4(y.xyz, -y.w);
}

// The cube in a cell is defined in WORLD space: the spin frame parallel-transported from the
// world origin to the cell centre. Map it back into the base cell so every path agrees.
void hbCellFrame(mat4 M, vec3 r0, vec3 r1, vec3 r2, out vec3 u0, out vec3 u1, out vec3 u2, out vec3 kc) {
    vec4 cw = M[3];
    float k = 1.0 / (1.0 + cw.w);
    vec3 c3 = cw.xyz;
    u0 = hbInvApply(M, vec4(r0 + c3 * dot(c3, r0) * k, dot(c3, r0))).xyz;
    u1 = hbInvApply(M, vec4(r1 + c3 * dot(c3, r1) * k, dot(c3, r1))).xyz;
    u2 = hbInvApply(M, vec4(r2 + c3 * dot(c3, r2) * k, dot(c3, r2))).xyz;
    u0 = normalize(u0);
    u1 = normalize(u1 - dot(u1, u0) * u0);
    u2 = normalize(u2 - dot(u2, u0) * u0 - dot(u2, u1) * u1);
    kc = c3 / cw.w;
}

vec3 hyperbolicHoneycomb(vec2 uv, float time, float cubeSize, float coneAngle, float coneIntensity, float fog, vec3 colorA, vec3 colorB, float speed, float echo, float music, float ripple) {
    // Klein half-width of the {4,3,5} cell: a^2 = sqrt(5) - 2 gives 72 degree dihedral angles
    const float A = 0.48586827;
    const float EDGE = 1.6169;          // edge length: acosh(phi^2)
    float period = EDGE * 4.0;

    // ---- Camera: glide along the honeycomb edge x = y = A, folding back into the base cell
    float sTot = mod(time * speed + EDGE * 0.6, period);   // start mid-flight, away from the loop seam
    vec4 p = vec4(A, A, 0.0, 1.0) / sqrt(1.0 - 2.0 * A * A);
    vec4 f = vec4(0.0, 0.0, 1.0, 0.0);
    vec4 c = hbTangent(vec4(-1.0, -1.0, 0.0, 0.0), p);
    vec4 h = vec4(0.70710678, -0.70710678, 0.0, 0.0);
    mat4 M = mat4(1.0);
    int steps = int(ceil(sTot / 0.35));
    float ds = sTot / float(max(steps, 1));
    for (int k = 0; k < 24; k++) {
        if (k >= steps) break;
        vec4 p2 = cosh(ds) * p + sinh(ds) * f;
        f = sinh(ds) * p + cosh(ds) * f;
        p = p2;
        for (int it = 0; it < 3; it++) {
            for (int i = 0; i < 6; i++) {
                vec4 fn = hbFace(i, A);
                if (hbDot(p, fn) > 1e-5) {
                    p = hbReflect(p, fn); f = hbReflect(f, fn); c = hbReflect(c, fn); h = hbReflect(h, fn);
                    M = hbReflectMat(M, fn);
                }
            }
        }
        p = hbPoint(p);
        f = hbTangent(f, p);
        c = hbTangent(c - hbDot(c, f) * f, p);
        h = hbTangent(h - hbDot(h, f) * f - hbDot(h, c) * c, p);
    }
    // Nudge off the edge, into the cell
    p = hbPoint(p + 0.004 * c);
    vec4 camWorld = M * p;   // where the camera really is, for light-travel delays
    f = hbTangent(f, p);
    c = hbTangent(c - hbDot(c, f) * f, p);
    h = hbTangent(h - hbDot(h, f) * f - hbDot(h, c) * c, p);

    float beta = 0.32;
    vec4 F = cos(beta) * f + sin(beta) * c;
    vec4 Rv = -sin(beta) * f + cos(beta) * c;
    float roll = time * 0.05;
    vec4 U = cos(roll) * h + sin(roll) * Rv;
    vec4 Rt = -sin(roll) * h + cos(roll) * Rv;
    vec4 v = hbTangent(F * 1.4 + Rt * uv.x + U * uv.y, p);

    // ---- Spinning cubes: each cell gets its own phase from its world-space centre
    vec3 r0, r1, r2;
    vec3 u0, u1, u2, kc;
    float cosCone = cos(coneAngle);
    float jitter = fract(sin(dot(uv, vec2(12.9898, 78.233)) + time) * 43758.5453);

    // Music: the beat travels outward from the camera, ripple beats per unit of distance
    float beatPh = u_beatPhase;
    float beatMusic = music * u_beatConfidence * smoothstep(0.25, 0.75, u_beatTrust); // beat couplings fade with the tracker confidence and the beat clock's trust

    vec3 col = vec3(0.0);
    vec3 glow = vec3(0.0);
    float D = 0.0;

    for (int it = 0; it < 32; it++) {
        vec3 kw = M[3].xyz / M[3].w;
        float ph = dot(kw, vec3(5.3, -4.1, 6.7));
        // Echo: this cell is seen as it was `distance * echo` seconds ago
        float cellDist = log(max(-hbDot(camWorld, M[3]), 1.0) + sqrt(max(hbDot(camWorld, M[3]) * hbDot(camWorld, M[3]) - 1.0, 0.0)));
        float ct = time - cellDist * echo;
        // Beat wavefront at this cell: a flare, and a spin surge that eases out over the beat (net zero per beat)
        float bph = fract(beatPh - cellDist * ripple);
        float flare = beatMusic * smoothstep(0.0, 0.04, bph) * exp(-bph * 4.5);
        float surge = beatMusic * 0.9 * (1.0 - pow(1.0 - bph, 3.0) - bph);
        float t1 = ct * 0.55 + ph * 1.7 + surge;
        float t2 = ct * 0.37 + ph * 2.3 + 1.0 + surge * 0.6;
        vec3 X0 = vec3(cos(t1), 0.0, -sin(t1));
        vec3 Z0 = vec3(sin(t1), 0.0, cos(t1));
        r0 = X0;
        r1 = vec3(0.0, 1.0, 0.0) * cos(t2) + cross(X0, vec3(0.0, 1.0, 0.0)) * sin(t2);
        r2 = Z0 * cos(t2) + cross(X0, Z0) * sin(t2);
        hbCellFrame(M, r0, r1, r2, u0, u1, u2, kc);
        float hue = 0.5 + 0.5 * sin(dot(kc, vec3(5.1, 3.7, -4.3)) + ct * 0.35);
        float pulse = 0.65 + 0.35 * sin(ct * 2.4 + ph);   // lamps breathe; the echo turns this into waves
        float lampPulse = pulse * (1.0 + 1.6 * flare);

        // Where does the ray leave this cell?
        float tExit = 0.99999;
        int exitFace = 0;
        for (int i = 0; i < 6; i++) {
            vec4 fn = hbFace(i, A);
            float vn = hbDot(v, fn);
            if (vn > 1e-7) {
                float t = max(-hbDot(p, fn) / vn, 0.0);
                if (t < tExit) { tExit = t; exitFace = i; }
            }
        }

        // Ray / cube: slab test along the projective ray X(t) = p + t v (t = tanh of distance)
        float tIn = 0.0;
        float tOut = tExit;
        int hitAx = -1;
        float hitSg = 0.0;
        for (int j = 0; j < 3; j++) {
            vec3 u = j == 0 ? u0 : (j == 1 ? u1 : u2);
            float ap = dot(u, p.xyz);
            float bv = dot(u, v.xyz);
            for (int k = 0; k < 2; k++) {
                float sg = k == 0 ? 1.0 : -1.0;
                float g0 = cubeSize * p.w - sg * ap;
                float g1 = cubeSize * v.w - sg * bv;
                if (abs(g1) < 1e-8) {
                    if (g0 < 0.0) tIn = 2.0;
                    continue;
                }
                float t = -g0 / g1;
                if (g1 > 0.0) {
                    if (t > tIn) { tIn = t; hitAx = j; hitSg = -sg; }
                } else {
                    tOut = min(tOut, t);
                }
            }
        }
        bool cubeHit = hitAx >= 0 && tIn <= tOut && tIn < tExit;
        float tEnd = cubeHit ? tIn : tExit;
        vec3 tint = mix(colorA, colorB, hue);

        // Volumetric light cones from this cell's cube (geodesics from the cell centre are Klein lines)
        float L = hbAtanh(tEnd);
        float dt = L / 12.0;
        for (int k = 0; k < 12; k++) {
            float dk = dt * (float(k) + jitter);
            float tt = tanh(dk);
            vec4 Xs = p + tt * v;
            vec3 K = Xs.xyz / Xs.w;
            float r = max(length(K), 1e-4);
            float rho = hbAtanh(r);
            float ca = abs(dot(K, u1)) / r;
            float cone = smoothstep(cosCone, mix(cosCone, 1.0, 0.5), ca);
            cone += 2.5 * smoothstep(mix(cosCone, 1.0, 0.7), 1.0, ca);
            float sh = sinh(rho);
            float fall = 1.0 / (1.0 + 3.0 * sh * sh);
            // the beat shell at this sample (D + dk = distance from the camera)
            float sph = fract(beatPh - (D + dk) * ripple);
            float shell = beatMusic * smoothstep(0.0, 0.05, sph) * exp(-sph * 6.0);
            glow += tint * cone * fall * dt * coneIntensity * pulse * (1.0 + 1.4 * shell) * exp(-(D + dk) * fog);
        }

        if (cubeHit) {
            vec4 Xh = p + tIn * v;
            vec3 K = Xh.xyz / Xh.w;
            vec3 cl = vec3(dot(K, u0), dot(K, u1), dot(K, u2)) / cubeSize;
            vec3 ac = abs(cl);
            float mx = max(ac.x, max(ac.y, ac.z));
            float mn = min(ac.x, min(ac.y, ac.z));
            float mid = ac.x + ac.y + ac.z - mx - mn;
            float edge = smoothstep(0.82, 0.96, mid);
            vec3 nrm = (hitAx == 0 ? u0 : (hitAx == 1 ? u1 : u2)) * hitSg;
            vec3 vd = normalize(v.xyz - K * v.w);
            float facing = max(dot(nrm, -vd), 0.0);
            vec3 surf = vec3(0.02, 0.025, 0.045) * (0.35 + 0.65 * facing);
            surf += tint * pow(1.0 - facing, 3.0) * 0.5;
            if (hitAx == 1) {
                float lens = 1.0 - smoothstep(0.5, 0.82, max(ac.x, ac.z));
                surf += (tint * 3.0 + vec3(1.2)) * lens * lampPulse;
            }
            surf += tint * edge * 2.5 * (1.0 + 0.8 * flare);
            col += surf * exp(-(D + hbAtanh(tIn)) * fog);
            D += hbAtanh(tIn);
            break;
        }

        // Step to the exit point, then reflect into the neighbouring cell
        float ch = 1.0 / sqrt(max(1.0 - tExit * tExit, 1e-9));
        vec4 pn = (p + tExit * v) * ch;
        vec4 vn = (tExit * p + v) * ch;
        D += hbAtanh(tExit);

        // Faint honeycomb wireframe where the ray crosses close to a cell edge
        vec3 ak = abs(pn.xyz / pn.w);
        int ej = exitFace / 2;
        float other = ej == 0 ? max(ak.y, ak.z) : (ej == 1 ? max(ak.x, ak.z) : max(ak.x, ak.y));
        float wire = smoothstep(A * 0.955, A * 0.997, other);
        col += tint * wire * 0.3 * exp(-D * fog) * smoothstep(0.3, 1.5, D);

        vec4 fn = hbFace(exitFace, A);
        p = hbPoint(hbReflect(pn, fn));
        v = hbTangent(hbReflect(vn, fn), p);
        M = hbReflectMat(M, fn);
    }

    col += glow;
    col += vec3(0.012, 0.008, 0.03) * (1.0 - exp(-D * fog));

    // Hide the loop seam with a short warp flash
    float w = sTot / period;
    float flash = smoothstep(0.975, 1.0, w) + 1.0 - smoothstep(0.0, 0.025, w);
    col = mix(col, vec3(0.9, 0.8, 1.3), clamp(flash, 0.0, 1.0) * 0.75);
    return col;
}

AnamorphicStreak.customGLSL:
// @node anamorphicStreak
// @title Anamorphic Streak
// @category effect
// @description Wide horizontal lens streak: blurs a bright-pass texture along x only (width in UV units).
vec3 anamorphicStreak(sampler2D tex, vec2 uv, float width) {
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = -16; i <= 16; i++) {
        float x = float(i) / 16.0;
        float wt = exp(-x * x * 4.0);
        acc += texture(tex, uv + vec2(x * width, 0.0)).rgb * wt;
        wsum += wt;
    }
    return acc / wsum;
}
